package com.yuegang.zhihui.product.application;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.product.api.ProductView;import java.time.*;import java.util.*;import java.util.function.*;import org.springframework.data.redis.core.StringRedisTemplate;
public final class ProductCacheService{private static final String MISS="__MISS__";private final StringRedisTemplate redis;private final ObjectMapper json;public ProductCacheService(StringRedisTemplate r,ObjectMapper j){redis=r;json=j;}public ProductView detail(String sku,Supplier<ProductView>loader){String key="ygh:product:detail:"+sku;try{String value=redis.opsForValue().get(key);if(MISS.equals(value))throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);if(value!=null)return json.readValue(value,ProductView.class);}catch(BusinessException e){throw e;}catch(Exception ignored){}try{ProductView loaded=loader.get();put(key,write(loaded),Duration.ofMinutes(10));return loaded;}catch(BusinessException e){if(e.errorCode()==ErrorCode.RESOURCE_NOT_FOUND)put(key,MISS,Duration.ofSeconds(30));throw e;}}public List<ProductView>list(String category,String keyword,int limit,Supplier<List<ProductView>>loader){String key="ygh:product:list:"+version()+":"+enc(category)+":"+enc(keyword)+":"+limit;try{String value=redis.opsForValue().get(key);if(value!=null)return json.readValue(value,new TypeReference<List<ProductView>>(){});}catch(Exception ignored){}List<ProductView>loaded=loader.get();put(key,write(loaded),Duration.ofMinutes(3));return loaded;}public void invalidate(String sku){try{redis.delete("ygh:product:detail:"+sku);redis.opsForValue().increment("ygh:product:catalog-version");}catch(RuntimeException ignored){}}private String version(){try{return Objects.requireNonNullElse(redis.opsForValue().get("ygh:product:catalog-version"),"0");}catch(RuntimeException e){return "0";}}private void put(String k,String v,Duration ttl){try{redis.opsForValue().set(k,v,ttl);}catch(RuntimeException ignored){}}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static String enc(String x){return x==null||x.isBlank()?"_":Base64.getUrlEncoder().withoutPadding().encodeToString(x.strip().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
